#!/bin/bash

set -e  # Abort in case of errors

# Get the root directory (parent of scripts directory)
SCRIPT_DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" && pwd )"
ROOT_DIR="$(dirname "$SCRIPT_DIR")"

echo "Cleaning up GeLB repository..."

# RM directories containing Python auto-generated bytecode
echo "Removing Python bytecode..."
find "$ROOT_DIR" -type d -name __pycache__ -exec rm -rf {} +

# RM pytest cache directory
echo "Removing pytest cache..."
rm -rf "$ROOT_DIR/.pytest_cache"

# RM files auto-generated by ANTLR4
echo "Removing ANTLR4 generated files..."
rm -rf "$ROOT_DIR/gelb/antlr_part/generated_code/"*.interp
rm -rf "$ROOT_DIR/gelb/antlr_part/generated_code/"*.tokens
rm -rf "$ROOT_DIR/gelb/antlr_part/generated_code/GeLB"{Lexer,Parser,Visitor}.py

rm -rf "$ROOT_DIR/gelb/antlr_part/grammars/.antlr/"

# Remove Python package build artifacts
echo "Removing Python package build artifacts..."
rm -rf "$ROOT_DIR"/*.egg-info
rm -rf "$ROOT_DIR/dist"
rm -rf "$ROOT_DIR/build"

echo "Repository cleanup complete!"
